    const limitSql = `LIMIT $${params.length - 1} OFFSET $${params.length}`;
    const sortKey = filters?.sort && PAGE_SORT_SQL[filters.sort] ? filters.sort : "updated_desc";
    const orderBy = PAGE_SORT_SQL[sortKey];
