  async findTrajectory(opts) {
    const limit = clampSearchLimit(opts.limit, 100, 500);
    const sinceDate = opts.since ? new Date(opts.since) : null;
    const untilDate = opts.until ? new Date(opts.until) : null;
    const metric = opts.metric ?? null;
    const kind = opts.kind ?? "all";
    const useArray = Array.isArray(opts.sourceIds) && opts.sourceIds.length > 0;
    const sourceIds = useArray ? opts.sourceIds : null;
    const sourceId = opts.sourceId ?? "default";
    const remoteFilter = opts.remote === true;
    const where = [
      useArray ? `source_id = ANY($1::text[])` : `source_id = $1`,
      `entity_slug = $2`,
      `expired_at IS NULL`
    ];
    const params = [useArray ? sourceIds : sourceId, opts.entitySlug];
    let p6 = 3;
    if (remoteFilter) {
      where.push(`visibility = 'world'`);
    }
    if (metric !== null) {
      where.push(`claim_metric = $${p6}`);
      params.push(metric);
      p6 += 1;
    }
    if (kind === "metric") {
      where.push(`claim_metric IS NOT NULL`);
    } else if (kind === "event") {
      where.push(`event_type IS NOT NULL`);
    }
    if (sinceDate) {
      where.push(`valid_from >= $${p6}`);
      params.push(sinceDate);
      p6 += 1;
    }
    if (untilDate) {
      where.push(`valid_from <= $${p6}`);
      params.push(untilDate);
      p6 += 1;
    }
    params.push(limit);
    const limitPlaceholder = p6;
    const sqlText = `
      SELECT id, valid_from,
             claim_metric, claim_value, claim_unit, claim_period,
             event_type,
             fact, source_session, source_markdown_slug,
             embedding
      FROM facts
      WHERE ${where.join(" AND ")}
      ORDER BY valid_from ASC, id ASC
      LIMIT $${limitPlaceholder}
    `;
    const result = await this.db.query(sqlText, params);
    return result.rows.map((r2) => {
      let embedding = null;
      if (r2.embedding != null) {
        if (r2.embedding instanceof Float32Array)
          embedding = r2.embedding;
        else if (Array.isArray(r2.embedding))
          embedding = new Float32Array(r2.embedding);
        else if (typeof r2.embedding === "string") {
          const trimmed = r2.embedding.trim();
          const inner = trimmed.startsWith("[") ? trimmed.slice(1, -1) : trimmed;
          const parts2 = inner.split(",").map((s5) => parseFloat(s5.trim())).filter(Number.isFinite);
          embedding = parts2.length > 0 ? new Float32Array(parts2) : null;
        }
      }
      return {
        fact_id: Number(r2.id),
        valid_from: r2.valid_from instanceof Date ? r2.valid_from : new Date(r2.valid_from),
        metric: r2.claim_metric,
        value: r2.claim_value === null ? null : Number(r2.claim_value),
        unit: r2.claim_unit,
        period: r2.claim_period,
        event_type: r2.event_type,
        text: r2.fact,
        source_session: r2.source_session,
        source_markdown_slug: r2.source_markdown_slug,
        embedding
      };
    });
  }
