  async getTakeEmbeddings(ids) {
    if (ids.length === 0)
      return new Map;
    const { rows } = await this.db.query(`SELECT id, embedding FROM takes WHERE id = ANY($1::bigint[]) AND embedding IS NOT NULL`, [ids]);
    const out2 = new Map;
    for (const r2 of rows) {
      const v4 = r2.embedding;
      if (typeof v4 === "string") {
        const trimmed = v4.replace(/^\[|\]$/g, "");
        const arr = trimmed.split(",").map(parseFloat).filter((n4) => !Number.isNaN(n4));
        out2.set(Number(r2.id), new Float32Array(arr));
      } else if (Array.isArray(v4)) {
        out2.set(Number(r2.id), new Float32Array(v4));
      }
    }
    return out2;
  }
