  async resolveSlugWithAlias(slug, sourceOrSources) {
    const sources = Array.isArray(sourceOrSources) ? [...sourceOrSources] : [sourceOrSources];
    if (sources.length === 0)
      return slug;
    try {
      const placeholders = sources.map((_4, i3) => `$${i3 + 2}`).join(",");
      const { rows } = await this.db.query(`SELECT canonical_slug, source_id
         FROM slug_aliases
         WHERE alias_slug = $1
           AND source_id IN (${placeholders})
         ORDER BY id`, [slug, ...sources]);
      if (rows.length === 0)
        return slug;
      if (rows.length > 1) {
        warnOncePerProcess(`resolveSlugWithAlias:multi_match:${slug}`, `[resolveSlugWithAlias] multi_match: alias '${slug}' exists in ${rows.length} sources; returning first.`);
      }
      const indexedRows = rows.map((r2) => ({
        ...r2,
        order: sources.indexOf(r2.source_id)
      }));
      indexedRows.sort((a2, b4) => a2.order - b4.order);
      return indexedRows[0].canonical_slug ?? slug;
    } catch (e) {
      if (isUndefinedTableError(e))
        return slug;
      throw e;
    }
  }
  async resolveAliases(aliasNorms, opts) {
    const out2 = new Map;
    if (!aliasNorms || aliasNorms.length === 0)
      return out2;
    const sources = opts?.sourceIds && opts.sourceIds.length > 0 ? opts.sourceIds : opts?.sourceId ? [opts.sourceId] : null;
    let q4 = `SELECT alias_norm, slug, source_id FROM page_aliases WHERE alias_norm = ANY($1::text[])`;
    const params = [aliasNorms];
    if (sources) {
      params.push(sources);
      q4 += ` AND source_id = ANY($2::text[])`;
    }
    q4 += ` ORDER BY alias_norm, source_id, slug`;
    const { rows } = await this.db.query(q4, params);
    for (const r2 of rows) {
      const list = out2.get(r2.alias_norm) ?? [];
      if (!list.some((x4) => x4.slug === r2.slug && x4.source_id === r2.source_id)) {
        list.push({ slug: r2.slug, source_id: r2.source_id });
      }
      out2.set(r2.alias_norm, list);
    }
    return out2;
  }
