    const updatedAfter = filters?.updated_after;
    const typeCondition = filters?.type ? sql2`AND p.type = ${filters.type}` : sql2``;
    const tagJoin = filters?.tag ? sql2`JOIN tags t ON t.page_id = p.id` : sql2``;
    const tagCondition = filters?.tag ? sql2`AND t.tag = ${filters.tag}` : sql2``;
    const updatedCondition = updatedAfter ? sql2`AND p.updated_at > ${updatedAfter}::timestamptz` : sql2``;
    const slugPrefix = filters?.slugPrefix;
    const slugCondition = slugPrefix ? sql2`AND p.slug LIKE ${slugPrefix.replace(/[\\%_]/g, (c3) => "\\" + c3) + "%"} ESCAPE '\\'` : sql2``;
    const sourceCondition = filters?.sourceIds && filters.sourceIds.length > 0 ? sql2`AND p.source_id = ANY(${filters.sourceIds}::text[])` : filters?.sourceId ? sql2`AND p.source_id = ${filters.sourceId}` : sql2``;
    const deletedCondition = filters?.includeDeleted === true ? sql2`` : sql2`AND p.deleted_at IS NULL`;
